        description: stringValue(value.description, true),
        appType: stringValue(value.appType),
        score: numberValue(value.score),
        recommendation: stringValue(value.recommendation),
        strategy: stringValue(value.strategy),
        license: stringValue(value.license),
        hasReadme: value.hasReadme === true,
        hasUi: value.hasUi === true,
        reasons: stringArray(value.reasons),
        risks: stringArray(value.risks),
